// Parse the AI agent output
const agentOutput = $input.first().json.output || $input.first().json.text || '';

// Check if no action items were found
if (agentOutput.trim() === 'NO_ACTION_ITEMS' || agentOutput.trim() === '') {
  return [{ json: { hasActions: false, actions: [] } }];
}

// Try to parse the JSON array of action items
try {
  // Extract JSON from the response (handle markdown code blocks)
  let jsonStr = agentOutput.trim();
  const jsonMatch = jsonStr.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    jsonStr = jsonMatch[0];
  }

  const actions = JSON.parse(jsonStr);

  if (!Array.isArray(actions) || actions.length === 0) {
    return [{ json: { hasActions: false, actions: [] } }];
  }

  return [{ json: { hasActions: true, actions: actions } }];
} catch (e) {
  // If parsing fails, treat the whole output as a single action item
  return [{ json: { hasActions: true, actions: [{ title: 'Review email action item', description: agentOutput, priority: 3 }] } }];
}

